import { pluginService } from './PluginService'
import { fsService } from './FileSystemService'
import type { MCPServer } from '../../shared/types/mcp'
import { CLAUDE_JSON_FILE } from '../../shared/constants'
import { readFile, writeFile } from 'fs/promises'
import { join, basename } from 'path'
import { existsSync } from 'fs'
import { homedir } from 'os'

interface ClaudeConfig {
  mcpServers?: Record<string, MCPServer>
  [key: string]: unknown
}

interface MCPTemplate {
  name: string
  description?: string
  type: 'stdio' | 'http'
  command?: string
  args?: string[]
  url?: string
  requiredEnvVars?: string[]
  pluginId: string
  pluginName: string
}

export class MCPService {
  async list(): Promise<MCPServer[]> {
    const config = await this.readClaudeConfig()
    const servers = config.mcpServers || {}

    return Object.entries(servers).map(([name, server]) => ({
      name,
      type: server.type,
      command: server.command,
      args: server.args,
      url: server.url,
      env: server.env,
      active: true
    }))
  }

  async listTemplates(): Promise<MCPTemplate[]> {
    const templates: MCPTemplate[] = []
    const plugins = await pluginService.list()
    const enabledPlugins = plugins.filter(p => p.enabled)

    for (const plugin of enabledPlugins) {
      const pluginTemplates = await this.loadPluginTemplates(plugin.id, plugin.name, plugin.installPath)
      templates.push(...pluginTemplates)
    }

    return templates
  }

  private async loadPluginTemplates(pluginId: string, pluginName: string, pluginPath: string): Promise<MCPTemplate[]> {
    const templates: MCPTemplate[] = []
    const mcpConfigsDir = join(pluginPath, 'mcp-configs')

    if (!existsSync(mcpConfigsDir)) {
      return templates
    }

    try {
      const { readdir } = await import('fs/promises')
      const files = await readdir(mcpConfigsDir)

      for (const file of files) {
        if (!file.endsWith('.json')) continue

        try {
          const filePath = join(mcpConfigsDir, file)
          const content = await readFile(filePath, 'utf-8')
          const template = JSON.parse(content) as Omit<MCPTemplate, 'pluginId' | 'pluginName'>

          templates.push({
            ...template,
            name: template.name || basename(file, '.json'),
            pluginId,
            pluginName
          })
        } catch (e) {
          console.error(`Failed to load MCP template ${file} from plugin ${pluginId}:`, e)
        }
      }
    } catch (e) {
      // Directory doesn't exist or other error
    }

    return templates
  }

  async activate(template: MCPTemplate, env: Record<string, string>): Promise<void> {
    const config = await this.readClaudeConfig()

    if (!config.mcpServers) {
      config.mcpServers = {}
    }

    const serverName = template.name

    // Merge provided env with template
    const mergedEnv = { ...template.env, ...env }

    config.mcpServers[serverName] = {
      name: serverName,
      type: template.type,
      command: template.command,
      args: template.args,
      url: template.url,
      env: mergedEnv,
      active: true,
      templateSource: template.pluginId
    }

    await this.writeClaudeConfig(config)
  }

  async deactivate(name: string): Promise<void> {
    const config = await this.readClaudeConfig()

    if (config.mcpServers && config.mcpServers[name]) {
      delete config.mcpServers[name]
      await this.writeClaudeConfig(config)
    }
  }

  async update(name: string, updates: Partial<MCPServer>): Promise<void> {
    const config = await this.readClaudeConfig()

    if (!config.mcpServers || !config.mcpServers[name]) {
      throw new Error(`MCP server "${name}" not found`)
    }

    const existing = config.mcpServers[name]

    config.mcpServers[name] = {
      ...existing,
      ...updates,
      name // Preserve original name
    }

    await this.writeClaudeConfig(config)
  }

  async setActive(name: string, active: boolean): Promise<void> {
    const config = await this.readClaudeConfig()

    if (!config.mcpServers || !config.mcpServers[name]) {
      throw new Error(`MCP server "${name}" not found`)
    }

    config.mcpServers[name].active = active
    await this.writeClaudeConfig(config)
  }

  private async readClaudeConfig(): Promise<ClaudeConfig> {
    // Try ~/.claude.json first
    if (await fsService.exists(CLAUDE_JSON_FILE)) {
      try {
        return await fsService.readJSON<ClaudeConfig>(CLAUDE_JSON_FILE)
      } catch {
        // Invalid JSON, return empty
      }
    }

    // Try project-level .mcp.json
    const projectMcpPath = join(process.cwd(), '.mcp.json')
    if (existsSync(projectMcpPath)) {
      try {
        const content = await readFile(projectMcpPath, 'utf-8')
        return JSON.parse(content)
      } catch {
        // Invalid JSON
      }
    }

    return {}
  }

  private async writeClaudeConfig(config: ClaudeConfig): Promise<void> {
    // Write to ~/.claude.json
    await fsService.writeJSON(CLAUDE_JSON_FILE, config, { spaces: 2 })
  }
}

export const mcpService = new MCPService()

import { create } from 'zustand'
import type { Agent } from '@shared/types/agent'

interface AgentStore {
  items: Agent[]
  loading: boolean
  fetch: () => Promise<void>
  deleteAgent: (name: string) => Promise<void>
}

export const useAgentStore = create<AgentStore>((set) => ({
  items: [],
  loading: false,
  async fetch() {
    if (!window.electronAPI) return
    set({ loading: true })
    try {
      const agents = await window.electronAPI.agents.list()
      set({ items: agents })
    } finally {
      set({ loading: false })
    }
  },
  async deleteAgent(name: string) {
    await window.electronAPI.agents.delete(name)
    set(state => ({ items: state.items.filter(a => a.name !== name) }))
  }
}))

import { create } from 'zustand'
import type { Skill } from '@shared/types/skill'

interface SkillFormData {
  name: string
  description: string
  userInvocable?: boolean
  disableModelInvocation?: boolean
  body: string
}

interface FileNode {
  name: string
  path: string
  isDirectory: boolean
  children?: FileNode[]
}

interface SkillStore {
  personal: Skill[]
  plugin: Skill[]
  loading: boolean
  directoryTree: { personal: FileNode[]; plugin: FileNode[] }
  fetch: () => Promise<void>
  createSkill: (name: string, data: SkillFormData) => Promise<void>
  updateSkill: (name: string, data: SkillFormData) => Promise<void>
  deleteSkill: (name: string) => Promise<void>
  getShadowedSkills: () => Skill[]
  fetchDirectoryTree: () => Promise<void>
  readFileContent: (filePath: string) => Promise<string | null>
  writeFileContent: (filePath: string, content: string) => Promise<void>
}

export const useSkillStore = create<SkillStore>((set, get) => ({
  personal: [],
  plugin: [],
  loading: false,
  directoryTree: { personal: [], plugin: [] },
  async fetch() {
    if (!window.electronAPI) return
    set({ loading: true })
    try {
      const data = await window.electronAPI.skills.list()
      set({ personal: data.personal, plugin: data.plugin })
    } finally {
      set({ loading: false })
    }
  },
  async createSkill(name: string, data: SkillFormData) {
    const metadata = {
      name: data.name,
      description: data.description,
      ...(data.userInvocable !== undefined && { userInvocable: data.userInvocable }),
      ...(data.disableModelInvocation !== undefined && { disableModelInvocation: data.disableModelInvocation })
    }
    await window.electronAPI.skills.write(name, data.body, metadata)
    await get().fetch()
  },
  async updateSkill(name: string, data: SkillFormData) {
    const metadata = {
      name: data.name,
      description: data.description,
      ...(data.userInvocable !== undefined && { userInvocable: data.userInvocable }),
      ...(data.disableModelInvocation !== undefined && { disableModelInvocation: data.disableModelInvocation })
    }
    await window.electronAPI.skills.write(name, data.body, metadata)
    await get().fetch()
  },
  async deleteSkill(name: string) {
    await window.electronAPI.skills.delete(name)
    await get().fetch()
  },
  getShadowedSkills() {
    const { personal, plugin } = get()
    const personalNames = new Set(personal.map(s => s.name))
    return plugin.filter(s => personalNames.has(s.name))
  },
  async fetchDirectoryTree() {
    const tree = await window.electronAPI.skills.getDirectoryTree()
    set({ directoryTree: tree })
  },
  async readFileContent(filePath: string) {
    return window.electronAPI.skills.readFile(filePath)
  },
  async writeFileContent(filePath: string, content: string) {
    await window.electronAPI.skills.writeFile(filePath, content)
  }
}))

