     1→import { useEffect, useState } from "react";
     2→import { useParams, useNavigate } from "react-router-dom";
     3→import { PageHeader } from "../components/shared/PageHeader";
     4→import { TerminalPanel } from "../components/shared/TerminalPanel";
     5→import { AVAILABLE_TOOLS, AVAILABLE_MODELS } from "@shared/types/agent";
     6→import { Terminal } from "lucide-react";
     7→import { useTranslation } from "../i18n/LanguageContext";
     8→
     9→export function AgentDetailPage(): JSX.Element {
    10→  const { name } = useParams<{ name: string }>();
    11→  const navigate = useNavigate();
    12→  const isNew = name === "new";
    13→  const { t } = useTranslation();
    14→
    15→  const [formName, setFormName] = useState("");
    16→  const [description, setDescription] = useState("");
    17→  const [tools, setTools] = useState<string[]>([
    18→    "Read",
    19→    "Write",
    20→    "Edit",
    21→    "Bash",
    22→    "Glob",
    23→    "Grep",
    24→  ]);
    25→  const [model, setModel] = useState("sonnet");
    26→  const [body, setBody] = useState("");
    27→  const [loading, setLoading] = useState(!isNew);
    28→  const [saving, setSaving] = useState(false);
    29→  const [isPlugin, setIsPlugin] = useState(false);
    30→  const [showTerminal, setShowTerminal] = useState(false);
    31→  const [isRunning, setIsRunning] = useState(false);
    32→
    33→  useEffect(() => {
    34→    if (!isNew && name) {
    35→      window.electronAPI.agents.read(name).then((agent) => {
    36→        if (agent) {
    37→          setFormName(agent.name);
    38→          setDescription(agent.description);
    39→          setTools(agent.tools);
    40→          setModel(agent.model);
    41→          setBody(agent.body);
    42→          setIsPlugin(agent.source === "plugin");
    43→        }
    44→        setLoading(false);
    45→      });
    46→    }
    47→  }, [name, isNew]);
    48→
    49→  const handleSave = async (): Promise<void> => {
    50→    if (!formName.trim()) return;
    51→    setSaving(true);
    52→    try {
    53→      const fileName = isNew
    54→        ? formName.trim().toLowerCase().replace(/\s+/g, "-")
    55→        : name!;
    56→      await window.electronAPI.agents.write(fileName, {
    57→        name: formName.trim(),
    58→        description,
    59→        tools,
    60→        model,
    61→        body,
    62→      });
    63→      navigate("/agents");
    64→    } finally {
    65→      setSaving(false);
    66→    }
    67→  };
    68→
    69→  const handleDelete = async (): Promise<void> => {
    70→    if (!name || isNew) return;
    71→    if (!confirm(t("agents.deleteConfirm", { name: name || "" }))) return;
    72→    await window.electronAPI.agents.delete(name);
    73→    navigate("/agents");
    74→  };
    75→
    76→  const toggleTool = (tool: string): void => {
    77→    setTools((prev) =>
    78→      prev.includes(tool) ? prev.filter((t) => t !== tool) : [...prev, tool],
    79→    );
    80→  };
    81→
    82→  const handleRunAgent = async (prompt: string): Promise<void> => {
    83→    if (!name) return;
    84→    setIsRunning(true);
    85→    try {
    86→      await window.electronAPI.cli.runAgent(name, prompt);
    87→    } catch (err) {
    88→      console.error("Failed to run agent:", err);
    89→    }
