                name: skill.name,
                description: skill.description,
                userInvocable: skill.userInvocable,
                disableModelInvocation: skill.disableModelInvocation,
                body: skill.body,
              }}
              onSave={handleSave}
              onCancel={() => setEditing(false)}
              saving={saving}
            />
          </div>
        ) : (
          <div className="flex gap-4 h-full">
