                          {t("common.cancel")}
                        </button>
                        <button
                          onClick={handleSaveFile}
                          disabled={saving}
                          className="px-3 py-1 text-xs rounded-lg bg-zinc-900 dark:bg-zinc-100 text-white dark:text-zinc-900 disabled:opacity-50"
